// client thread: queue the request, keep its future
std::future<void> Proxy::put(Message m) {
    std::packaged_task<void()> t([this, m] { servant_.put_i(m); });
    auto f = t.get_future();
    { std::lock_guard lk(m_); q_.push(std::move(t)); } cv_.notify_one(); return f;
}
// scheduler thread: dequeue and run on the servant
for (std::packaged_task<void()> t; !stop_; ) {
    std::unique_lock lk(m_);
    cv_.wait(lk, [&] { return stop_ || !q_.empty(); });
    t = std::move(q_.front()); q_.pop(); lk.unlock(); t();
}

