boost::asio::strand<boost::asio::io_context::executor_type> strand_{io_.get_executor()};
std::deque<Message> q_;
std::future<void> put(Message m) {                       // proxy
    auto p = std::make_shared<std::promise<void>>();
    boost::asio::post(strand_, [this, m, p] {
        q_.push_back(m);                                 // serialized by the strand
        p->set_value();
    });
    return p->get_future();
}

class Put : public ACE_Method_Request {
public:
    Put(MQ_Servant *s, const Message &m) : servant_(s), msg_(m) {}
    int call() override  { return servant_->put_i(msg_); }
    int guard() override { return !servant_->full_i(); }
private:
    MQ_Servant *servant_;
    Message msg_;
};
